{"path": "grep.py", "content": "def grep(pattern, flags, files):
    if isinstance(flags, str):
        flags = flags.split()
    flags = set(flags)
    multi = len(files) > 1
    needle = pattern.lower() if "-i" in flags else pattern
    out = []
    for name in files:
        with open(name) as f:
            lines = f.read().splitlines()
        for num, line in enumerate(lines, 1):
            hay = line.lower() if "-i" in flags else line
            hit = hay == needle if "-x" in flags else needle in hay
            if hit == ("-v" in flags):
                continue
            if "-l" in flags:
                out.append(name + "\n")
                break
            prefix = ""
            if multi:
                prefix += name + ":"
            if "-n" in flags:
                prefix += str(num) + ":"
            out.append(prefix + line + "\n")
    return "".join(out)
